   223→    // Handle receiver postal code manual input
   224→    const receiverManualInput = document.querySelector('input[name="receiver_postal_code_manual"]')
   225→    if (receiverManualInput) {
   226→      receiverManualInput.readOnly = enabled
   227→      receiverManualInput.classList.toggle("bg-white", !enabled)
   228→      receiverManualInput.classList.toggle("bg-gray-100", enabled)
   229→    }
   230→
   231→    // Handle receiver postal code toggle buttons
   232→    const receiverPostalButtons = document.querySelectorAll('#receiver-postal-code-group button')
   233→    receiverPostalButtons.forEach(button => {
   234→      button.style.pointerEvents = enabled ? 'none' : 'auto'
   235→      button.classList.toggle('opacity-50', enabled)
   236→    })
