import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  static targets = ["toggle"]

  connect() {
    this.boundSync = this.syncFields.bind(this)
    this.boundSyncToManual = () => { setTimeout(() => this.syncToReceiverManual(), 50) }
    this.boundSyncToSelect = () => { setTimeout(() => this.syncToReceiverSelect(), 50) }
  }

  toggle() {
    const isChecked = this.toggleTarget.checked
    if (isChecked) {
      // switch to manual first, then copy with a small delay
      this.switchReceiverToManual()
      setTimeout(() => {
        this.copyAllFields()
        this.startSync()
      }, 0)
    } else {
      this.stopSync()
      this.switchReceiverToSelect()
    }
    this.setReadonlyState(isChecked)
  }

  startSync() {
    clearTimeout(this._syncTimer)
    this._syncTimer = setTimeout(() => {
      this.leftFields().forEach(field => {
        field.addEventListener('input', this.boundSync)
        field.addEventListener('change', this.boundSync)
      })
    }, 0)
  }

  stopSync() {
    this.leftFields().forEach(field => {
      field.removeEventListener('input', this.boundSync)
      field.removeEventListener('change', this.boundSync)
    })
  }

  syncFields() {
    if (this.toggleTarget.checked) {
      this.copyAllFields()
    }
  }

  copyAllFields() {
    const pairs = [
      ["customer_name", "receiver_name"],
      ["customer_no_handphone", "receiver_no_handphone"],
      ["customer_email", "receiver_email"],
      ["customer_postal_code", "receiver_postal_code"],
      ["customer_address", "receiver_address"]
    ]

    pairs.forEach(([from, to]) => {
      const fromEl = document.querySelector(`[name='${from}'], #${from}`)
      const toEl = document.querySelector(`[name='${to}']`)

      if (fromEl && toEl && (!toEl.value || this.toggleTarget.checked)) {

        if (from === "customer_postal_code") {
          // postal code copy: read from whichever customer input is visible, write to active receiver input
          const customerSelectEl = document.querySelector("select[name='customer_postal_code']")
          const customerManualEl = document.querySelector("input[name='customer_postal_code_manual']")
          let customerPostalValue = ""

          if (customerManualEl && this.isElementVisible(customerManualEl) && customerManualEl.value) {
            customerPostalValue = customerManualEl.value
          } else if (customerSelectEl && this.isElementVisible(customerSelectEl) && customerSelectEl.value) {
            customerPostalValue = customerSelectEl.value
          }

          const receiverActivePostal = this.getActivePostalInput('receiver_postal_code', 'receiver_postal_code_manual')
          if (receiverActivePostal) {
            if (receiverActivePostal.tomselect) {
              receiverActivePostal.tomselect.setValue(customerPostalValue, false)
            } else {
              receiverActivePostal.value = customerPostalValue
            }
            receiverActivePostal.dispatchEvent(new Event('input', { bubbles: true }))
            receiverActivePostal.dispatchEvent(new Event('change', { bubbles: true }))
          }
        }

        // generic copy for other fields
        const fromEl = document.querySelector(`[name='${from}'], #${from}`)
        const toEl = document.querySelector(`[name='${to}']`)
        if (!fromEl || !toEl) return
        if (!toEl.value || this.toggleTarget.checked) {
        if (toEl.tomselect) {
          toEl.tomselect.setValue(fromEl.value, false)
        } else {
          toEl.value = fromEl.value
        }
        toEl.dispatchEvent(new Event('input', { bubbles: true }))
        toEl.dispatchEvent(new Event('change', { bubbles: true }))
        }
      }
    })

    const fromPostal = this.getActivePostalInput('customer_postal_code', 'customer_postal_code_manual')?.getAttribute('name') || 'customer_postal_code_manual'
    const toPostal = this.getActivePostalInput('receiver_postal_code', 'receiver_postal_code_manual')?.getAttribute('name') || 'receiver_postal_code_manual'

    this.copyLocationSelect("province", "customer_province", "receiver_province", () => {
      this.copyLocationSelect("regency", "customer_city", "receiver_city", () => {
        this.copyLocationSelect("district", "customer_district", "receiver_district", () => {
          this.copyLocationSelect("village", "customer_subdistrict", "receiver_subdistrict", () => {
            this.copyLocationSelect("postal_code", fromPostal, toPostal, () => {})
          })
        })
      })
    })
  }

  copyLocationSelect(level, fromName, toName, callback = null) {
    const fromEl = document.querySelector(`[name='${fromName}']`)
    const toEl = document.querySelector(`[name='${toName}']`)

    if (!fromEl || !toEl) return

    // Get value from Tom Select if it exists, otherwise from regular select
    const valueToCopy = fromEl.tomselect ? fromEl.tomselect.getValue() : fromEl.value
    const currentToValue = toEl.tomselect ? toEl.tomselect.getValue() : toEl.value

    if (!valueToCopy || currentToValue === valueToCopy) {
      if (callback) callback()
      return
    }

    // Handle Tom Select instances
    if (toEl.tomselect) {
      toEl.tomselect.setValue(valueToCopy, false)
    } else {
      toEl.value = valueToCopy
    }
    toEl.dispatchEvent(new Event('change', { bubbles: true }))

    if (callback) { // delay
      setTimeout(callback, 500)
    }
  }  

  leftFields() {
    return Array.from(document.querySelectorAll("[name^='customer_']"))
  }

  getActivePostalInput(nameSelect, nameManual) {
    const selectEl = document.querySelector(`select[name='${nameSelect}']`)
    const manualEl = document.querySelector(`input[name='${nameManual}']`)
    // active = visible element
    if (manualEl && this.isElementVisible(manualEl)) return manualEl
    if (selectEl && this.isElementVisible(selectEl)) return selectEl
    // fallback to manual
    return manualEl || selectEl
  }

  setReadonlyState(enabled) {
    const inputNames = [
      "receiver_name", "receiver_no_handphone", "receiver_email", "receiver_address"
    ]
    const selectNames = [
      "receiver_province", "receiver_city", "receiver_district", "receiver_subdistrict", "receiver_postal_code"
    ]

    inputNames.forEach(name => {
      const el = document.querySelector(`[name='${name}']`)
      if (el) {
        el.readOnly = enabled
        el.classList.toggle("bg-white", !enabled)
        el.classList.toggle("bg-gray-100", enabled)
      }
    })

    selectNames.forEach(name => {
      const el = document.querySelector(`[name='${name}']`)
      if (el) {
        el.classList.toggle("bg-white", !enabled)
        el.classList.toggle("bg-gray-100", enabled)
        el.style.pointerEvents = enabled ? 'none' : 'auto'
      }
    })

    // Handle postal code manual input and toggle buttons
    this.setPostalCodeReadonlyState(enabled)
  }

  syncToReceiverManual() {
    if (!this.toggleTarget.checked) return
    this.switchReceiverToManual()
  }

  syncToReceiverSelect() {
    if (!this.toggleTarget.checked) return
    this.switchReceiverToSelect()
  }

  switchReceiverToManual() {
    const receiverGroup = document.querySelector('#receiver-postal-code-group')
    if (!receiverGroup) return

    const postalCodeController = this.application.getControllerForElementAndIdentifier(receiverGroup, 'postal-code-toggle')
    if (postalCodeController) {
      postalCodeController.showManual()
    }
  }

  switchReceiverToSelect() {
    const receiverGroup = document.querySelector('#receiver-postal-code-group')
    if (!receiverGroup) return

    const postalCodeController = this.application.getControllerForElementAndIdentifier(receiverGroup, 'postal-code-toggle')
    if (postalCodeController) {
      postalCodeController.showSelect()
    }
  }

  setPostalCodeReadonlyState(enabled) {
    // Handle receiver postal code manual input
    const receiverManualInput = document.querySelector('input[name="receiver_postal_code_manual"]')
    if (receiverManualInput) {
      receiverManualInput.readOnly = enabled
      receiverManualInput.classList.toggle("bg-white", !enabled)
      receiverManualInput.classList.toggle("bg-gray-100", enabled)
    }

    // Handle receiver postal code toggle buttons
    const receiverPostalButtons = document.querySelectorAll('#receiver-postal-code-group button')
    receiverPostalButtons.forEach(button => {
      button.style.pointerEvents = enabled ? 'none' : 'auto'
      button.classList.toggle('opacity-50', enabled)
    })
  }

  isElementVisible(element) {
    if (!element) return false

    // Check if element has display: none in style attribute
    if (element.style.display === 'none') return false

    // Check computed style for display
    const computedStyle = window.getComputedStyle(element)
    if (computedStyle.display === 'none') return false

    // Element is visible
    return true
  }

}

